app.addEventListener('click',e=>{const el=e.target.closest('button');if(!el||el.disabled)return;invalidate();if(el.dataset.hero){navigate('character',el.dataset.hero);return;}if(el.dataset.open){navigate(el.dataset.open,el.dataset.id);return;}if(el.dataset.nav){navigate(el.dataset.nav,el.dataset.nav==='journey'?state.journey:'atlas');return;}if(el.dataset.detail){state.detail=el.dataset.detail;renderPage();return;}if(el.dataset.frame!==undefined){setFrame(Number(el.dataset.frame));return;}if(el.dataset.map){state.map=el.dataset.map;renderPage();setScene('atlas');return;}if(el.dataset.journey){journeyMemory[state.journey]=state.step;state.journey=el.dataset.journey;state.step=journeyMemory[state.journey]||0;state.playing=false;$('#journey-play').innerHTML=svg('play');renderPage();setScene('atlas');return;}if(el.dataset.step!==undefined){chooseJourneyStep(Number(el.dataset.step));return;}
 switch(el.id){case 'landscape':landscapeView();break;case 'plan':togglePlan();break;case 'start-journey':navigate('journey',state.map);break;case 'journey-back':chooseJourneyStep(Math.max(0,Math.ceil(state.step)-1));break;case 'journey-next':chooseJourneyStep(Math.min(journeys[state.journey].steps.length-1,Math.floor(state.step)+1));break;case 'journey-region':{const region=journeys[state.journey].steps[Math.floor(state.step)].region;if(region)navigate('region',region);break;}case 'journey-card-toggle':{const expanded=el.getAttribute('aria-expanded')==='true';el.setAttribute('aria-expanded',String(!expanded));el.textContent=expanded?'+':'−';$('#journey-card-body').hidden=expanded;$('#journey-card').classList.toggle('collapsed',expanded);break;}case 'visit':visit(0);break;case 'tour-prev':visit(tourIndex-1);break;case 'tour-next':visit(tourIndex+1);break;case 'tour-end':endVisit();break;case 'source-map':showSourceMaps();break;case 'map-ref-close':$('#map-reference').hidden=true;break;case 'close-book':closeBook();break;case 'audio':toggleAudio();break;case 'colophon':$('#info-dialog').showModal();break;case 'dialog-close':$('#info-dialog').close();break;case 'reset':if(current)endVisit();break;case 'zoom-in':case 'zoom-out':if(camera){const offset=camera.position.clone().sub(controls.target),distance=THREE.MathUtils.clamp(offset.length()*(el.id==='zoom-in'?.8:1.2),controls.minDistance,controls.maxDistance);moveCamera(controls.target.clone().add(offset.setLength(distance)).toArray(),controls.target.toArray(),.4);}break;case 'rotate':if(controls){controls.autoRotate=!controls.autoRotate;el.setAttribute('aria-pressed',String(controls.autoRotate));}break;case 'light':state.night=!state.night;applyLight();break;case 'cutaway':leavePlan();markShadow();state.cutaway=!state.cutaway;current?.group.traverse(o=>{if(o.userData?.cutawayShell)o.visible=!state.cutaway;});el.setAttribute('aria-pressed',String(state.cutaway));el.textContent=state.cutaway?'Zamknij przekrój':'Wnętrze Bag End';if(state.cutaway){const inside=current.tours?.find(t=>t.cutaway);moveCamera(current.cutawayCamera||inside?.position||current.camera,current.cutawayTarget||inside?.target||current.target);}else moveCamera(fittedCamera(current),current.target);break;case 'labels':state.labels=!state.labels;$('#map-labels').style.display=state.labels?'':'none';el.setAttribute('aria-pressed',String(state.labels));if(state.labels)queueMapLeaderLayout();invalidate();break;case 'immersive':setImmersive(true);break;case 'restore-ui':setImmersive(false);break;case 'capture':capture();break;case 'export':exportModel();break;case 'journey-play':if(state.step>=journeys[state.journey].steps.length-1)setStep(0);state.playing=!state.playing;el.innerHTML=svg(state.playing?'pause':'play');updateJourneyUI();break;case 'journey-follow':state.follow=!state.follow;transition=null;el.setAttribute('aria-pressed',String(state.follow));if(state.follow&&route){const view=journeyView(route.update(state.step),44);moveCamera(view.position.toArray(),view.target.toArray());}break;case 'mobile-index':setIndexOpen(!$('#sidebar').classList.contains('mobile-open'));break;case 'close-index':case 'index-dismiss':setIndexOpen(false);$('#mobile-index').focus({preventScroll:true});break;case 'previous-page':case 'next-page':{const pages=['atlas',...regions.map(x=>x.id),...characters.map(x=>x.id)],i=pages.indexOf(state.id)+(el.id==='next-page'?1:-1),id=pages[THREE.MathUtils.clamp(i,0,pages.length-1)];navigate(id==='atlas'?'atlas':characters.some(c=>c.id===id)?'character':'region',id,el.id==='previous-page'?-1:1);break;}}
});
$('#tour-select').addEventListener('change',e=>visit(Number(e.target.value)));
$('#journey-stops').addEventListener('change',e=>chooseJourneyStep(Number(e.target.value)));
$('#journey-speed').addEventListener('change',e=>{state.speed=Number(e.target.value);});
$('#journey-range').addEventListener('change',e=>chooseJourneyStep(Number(e.target.value)));
document.addEventListener('keydown',e=>{if(app.hidden||$('#info-dialog').open||state.mode!=='journey'||e.target.closest?.('input,select,textarea,[role=tablist]'))return;if(e.key==='ArrowRight'){e.preventDefault();chooseJourneyStep(Math.floor(state.step)+1);}if(e.key==='ArrowLeft'){e.preventDefault();chooseJourneyStep(Math.ceil(state.step)-1);}});
$('#journey-range').addEventListener('input',e=>{state.playing=false;$('#journey-play').innerHTML=svg('play');setStep(Number(e.target.value),false);});$('#quality').addEventListener('change',e=>setQuality(e.target.value));
$('#info-dialog').addEventListener('click',e=>{if(e.target===$('#info-dialog'))$('#info-dialog').close();});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'&&!app.hidden){if($('#info-dialog').open)return;if(!$('#map-reference').hidden){$('#map-reference').hidden=true;return;}if($('#sidebar').classList.contains('mobile-open')){setIndexOpen(false);$('#mobile-index').focus({preventScroll:true});return;}if(state.immersive){setImmersive(false);return;}if(tourIndex>=0||state.plan||state.cutaway)endVisit();}
 const list=e.target.closest?.('[role="tablist"]');if(list&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){const tabs=[...list.querySelectorAll('[role="tab"]')],i=tabs.indexOf(e.target),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;e.preventDefault();tabs[next]?.click();const updated=$('#page-content').querySelector('[role="tablist"]');updated?.querySelectorAll('[role="tab"]')[next]?.focus({preventScroll:true});}
});
async function openBook(){
 if(openingBook)return openingBook;
 openingBook=(async()=>{clearTimeout(coverTimer);const trigger=$('#open-book');trigger.disabled=true;trigger.textContent='Rozkładanie księgi…';app.hidden=false;app.inert=true;$('#cover').classList.add('opening');if(!renderer)initRenderer();syncAnimationLoop();
 try{if(!current)await navigate(state.mode,state.mode==='journey'?state.journey:state.id);applyQuality($('#quality').value);resize();scheduleStoryFrames(state.id);await new Promise(resolve=>{coverTimer=setTimeout(resolve,reducedMotion.matches?0:750);});$('#cover').hidden=true;app.inert=false;$('.main-nav .active')?.focus({preventScroll:true});}finally{trigger.disabled=false;trigger.innerHTML='Otwórz księgę <span aria-hidden="true">✦</span>';openingBook=null;}
 })();return openingBook;
}
function closeBook(){clearTimeout(leafTimer);$('.turn-leaf')?.remove();setIndexOpen(false);setImmersive(false);state.playing=false;updateJourneyUI();$('#cover').hidden=false;$('#cover').classList.remove('opening');app.hidden=true;app.inert=true;syncAnimationLoop();$('#open-book').focus({preventScroll:true});}
$('#open-book').addEventListener('click',openBook);
document.addEventListener('visibilitychange',()=>{if(document.hidden){state.playing=false;updateJourneyUI();}syncAnimationLoop();});
reducedMotion.addEventListener('change',()=>{transition=null;invalidate();});
window.addEventListener('pagehide',()=>{renderer?.setAnimationLoop(null);clearTimeout(framePreviewTimer);});
window.addEventListener('pageshow',syncAnimationLoop);
try{const quality=sessionStorage.getItem('atlas-quality');if(['auto','cinematic','ultra','light'].includes(quality))$('#quality').value=quality;}catch{}
renderPage();

// Optional browser tool interface: it navigates only within the same book.
if(navigator.modelContext?.registerTool){try{navigator.modelContext.registerTool({name:'open_atlas_chapter',description:'Open a chapter of the Middle-earth atlas. Available chapters: atlas, shire, bree, rivendell, gondor, rohan, mordor, eye, bilbo, frodo, gandalf.',inputSchema:{type:'object',properties:{chapter:{type:'string',enum:['atlas',...regions.map(r=>r.id),...characters.map(c=>c.id)]}},required:['chapter']},execute:async({chapter})=>{if(app.hidden)await openBook();await navigate(chapter==='atlas'?'atlas':characters.some(c=>c.id===chapter)?'character':'region',chapter);return {content:[{type:'text',text:`Opened ${chapter}`}]};}});}catch{}}
